<div class="gal-admin"><div class="section-head"><div><span class="gal-admin-eyebrow">CONTENT LIBRARY</span><h1>Gallery <small><?= number_format($total) ?> อัลบั้ม</small></h1><p>จัดเก็บภาพความประทับใจ แล้วส่งต่อเรื่องราวการเดินทาง</p></div><div class="gal-actions"><a class="outline-link" href="<?= base_url().'gallery' ?>" target="_blank" rel="noopener">ดูหน้าเว็บไซต์ ↗</a><a class="btn" href="<?= base_url().'admin/gallery/new' ?>">+ สร้างอัลบั้ม</a></div></div><form class="panel gal-filters" method="get"><label class="gal-search">ค้นหา<input name="q" type="search" value="<?= e($filters['q']) ?>" placeholder="ชื่ออัลบั้ม หรือสถานที่"></label><label>สถานะ<select name="status"><option value="">ทุกสถานะ</option><option value="published" <?= $filters['status']==='published' ? 'selected' : '' ?>>เผยแพร่แล้ว</option><option value="draft" <?= $filters['status']==='draft' ? 'selected' : '' ?>>ฉบับร่าง</option></select></label><label>หมวดหมู่<select name="category"><option value="">ทุกหมวดหมู่</option><?php foreach ($categories as $c): ?><option value="<?= e($c) ?>" <?= $filters['category']===$c ? 'selected' : '' ?>><?= e($c) ?></option><?php endforeach ?></select></label><button class="btn" type="submit">ค้นหา</button><a href="<?= base_url().'admin/gallery' ?>">ล้าง</a></form>
<?php if (!$albums): ?><div class="panel gal-empty"><span>▧</span><h2>ยังไม่มีอัลบั้มในรายการนี้</h2><p>เริ่มสร้างอัลบั้มแรก หรือปรับตัวกรองเพื่อค้นหาอีกครั้ง</p><a class="btn" href="<?= base_url().'admin/gallery/new' ?>">สร้างอัลบั้มใหม่</a></div><?php else: ?><div class="gal-admin-grid"><?php foreach ($albums as $a): ?><article class="panel gal-admin-card"><a href="<?= base_url().'admin/gallery/'.$a['id'] ?>"><img src="<?= e(base_url().($a['cover'] ?: 'public/images/story.jpg')) ?>" alt="<?= e($a['title']) ?>" loading="lazy"></a><div><span class="gal-status <?= $a['status']==='published' ? 'is-live' : '' ?>"><?= $a['status']==='published' ? '● เผยแพร่แล้ว' : '○ ฉบับร่าง' ?></span><h2><a href="<?= base_url().'admin/gallery/'.$a['id'] ?>"><?= e($a['title']) ?></a></h2><p><?= e($a['category'] ?: 'ไม่มีหมวดหมู่') ?> · <?= (int)$a['photo_count'] ?> ภาพ</p><div class="gal-actions"><a class="outline-link" href="<?= base_url().'admin/gallery/'.$a['id'] ?>">แก้ไขอัลบั้ม</a><?php if ($a['status']==='published'): ?><a href="<?= base_url().'gallery/'.$a['id'] ?>" target="_blank" rel="noopener">ดูอัลบั้ม ↗</a><?php endif ?><form class="gal-card-delete" action="<?= base_url().'admin/gallery/'.$a['id'].'/delete' ?>" method="post" data-gallery-delete="<?= e($a['title']) ?>"><?= csrf_field() ?><input type="hidden" name="revision" value="<?= (int)$a['revision'] ?>"><button type="submit" class="outline-link gal-danger" aria-label="ลบอัลบั้ม <?= e($a['title']) ?>">ลบ</button></form></div></div></article><?php endforeach ?></div><?php endif ?><?php load_view('gallery/pagination',['base'=>'admin/gallery']); ?></div>
